head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > isMobile]<br/>현재 동작 중인 기기가 모바일 환경인지 판별하여 결과를 반환합니다.",
    "validation" : [
        "모바일 기기이면 true 를 반환해야 합니다.",
        "모바일 기기가 아니면 false 를 반환해야 합니다.",
        "isMobileDevice 파라미터 생략 시 기본값(undefined)으로 동작해야 합니다.",
        "isMobileDevice 파라미터를 true 로 설정하면 데스크탑 모드에 관계없이 모바일 기기 자체를 판별해야 합니다.",
        "isMobileDevice 파라미터를 false 로 설정하면 데스크탑 모드가 활성화된 경우 모바일로 판별하지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_isMobile_onclick = function () {
    let ret = WebSquare.util.isMobile();
    wf_body_bottom.getObj("scwin").setReturnValue("isMobile() : " + ret);
}

scwin.btn_isMobile_true_onclick = function () {
    let ret = WebSquare.util.isMobile(true);
    wf_body_bottom.getObj("scwin").setReturnValue("isMobile(true) : " + ret);
}

scwin.btn_isMobile_false_onclick = function () {
    let ret = WebSquare.util.isMobile(false);
    wf_body_bottom.getObj("scwin").setReturnValue("isMobile(false) : " + ret);
}
